--- a/src/query.ts
+++ b/src/query.ts
@@ -1,6 +1,44 @@
 export type Query = Record<string, string | string[]>;

-/** Parse a URL query string. See README.md for the rules. */
+function decodeValue(s: string): string {
+  s = s.replace(/\+/g, " ");
+  try {
+    return decodeURIComponent(s);
+  } catch {
+    return s;
+  }
+}
+
 export function parseQuery(query: string): Query {
-  throw new Error("not implemented");
+  const result: Query = {};
+  const s = query.startsWith("?") ? query.slice(1) : query;
+  if (s === "") return result;
+
+  for (const pair of s.split("&")) {
+    if (pair === "") continue;
+    const eqIdx = pair.indexOf("=");
+    let key: string;
+    let value: string;
+    if (eqIdx === -1) {
+      key = pair;
+      value = "";
+    } else {
+      key = pair.slice(0, eqIdx);
+      value = pair.slice(eqIdx + 1);
+    }
+    key = decodeValue(key);
+    value = decodeValue(value);
+
+    if (key in result) {
+      const existing = result[key];
+      if (Array.isArray(existing)) {
+        existing.push(value);
+      } else {
+        result[key] = [existing, value];
+      }
+    } else {
+      result[key] = value;
+    }
+  }
+  return result;
 }
